def link_open_disputes(apps, schema_editor):
    """旧待处理工单无需重新接单，即可使用原会话或补建共享会话。"""
    alias = schema_editor.connection.alias
    disputes = apps.get_model("communication", "Dispute").objects.using(alias)
    conversations = apps.get_model("communication", "Conversation").objects.using(alias)
    unlinked = disputes.filter(status="待处理", conversation__isnull=True).select_related("order")
    for ticket in unlinked.iterator():
        order = ticket.order
        chat, _ = conversations.get_or_create(
            product_id=order.product_id, buyer_id=order.buyer_id, seller_id=order.seller_id,
            defaults={"order_id": order.pk},
        )
        disputes.filter(pk=ticket.pk).update(conversation_id=chat.pk)


